package com.drogaria.backend.controller;
import com.drogaria.backend.dto.LoteRequest; import com.drogaria.backend.dto.LoteResponse; import com.drogaria.backend.service.LoteService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/lote") public class LoteController { private final LoteService s; public LoteController(LoteService s){this.s=s;} @GetMapping public List<LoteResponse> listar(){return s.listar();} @GetMapping("/{numeroLote}") public LoteResponse buscar(@PathVariable String numeroLote){return s.buscar(numeroLote);} @PostMapping public ResponseEntity<LoteResponse> salvar(@Valid @RequestBody LoteRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.salvar(r));} @PutMapping("/{numeroLote}") public LoteResponse atualizar(@PathVariable String numeroLote,@Valid @RequestBody LoteRequest r){return s.salvar(r);} @DeleteMapping("/{numeroLote}") public ResponseEntity<Void> excluir(@PathVariable String numeroLote){s.excluir(numeroLote);return ResponseEntity.noContent().build();} }